def digitCount(num: str) -> bool:
    # Count occurrences of each digit (as character) in num
    count = [0] * 10  # Since digits are '0'-'9'
    for c in num:
        count[int(c)] += 1

    # For each index, verify that num[i] == count[i] (as string vs integer)
    n = len(num)
    for i in range(n):
        if int(num[i]) != count[i]:
            return False
    return True
